-- Catalog-only upsert. Existing questlines and exercises are preserved.
insert into public.catalog_entries (kind, external_id, name, description, status, image_path, metadata) select kind, external_id, name, description, status, image_path, metadata from jsonb_to_recordset($seed$[{"kind":"minigame","external_id":"letter_ordering","name":"Letter Ordering","description":"Arrange scrambled letter tiles to spell a target English word.","status":null,"image_path":"images/minigames/letter_ordering.png","metadata":{"image":"images/minigames/letter_ordering.png","name":"Letter Ordering","unity_config":"LetterOrderingQuestConfigSO","unity_content":"LetterOrderingDataSO","category":"spelling","description":"Arrange scrambled letter tiles to spell a target English word.","english_focus":"Spelling, letter recognition","difficulty_range":[1,6],"content_fields":["prompt","targetWord","extraDistractorCount","customDistractors","visualVariant","promptAudio","hintMode","wordRevealDatabase"],"variants":["word_spelling"],"typical_stations":["chest","cart","tombstone","exam_table"]}},{"kind":"minigame","external_id":"listening_letter_ordering","name":"Listen & Build","description":"Listen to the assigned English recording, then arrange letters to spell the word. Separate teal and gold visuals, replay button, and optional text clue. Uses the shared Letter Ordering validation.","status":null,"image_path":"images/minigames/listening_letter_ordering.png","metadata":{"image":"images/minigames/listening_letter_ordering.png","name":"Listen & Build","unity_config":"LetterOrderingQuestConfigSO","unity_content":"LetterOrderingDataSO","category":"spelling","description":"Listen to the assigned English recording, then arrange letters to spell the word. Separate teal and gold visuals, replay button, and optional text clue. Uses the shared Letter Ordering validation.","english_focus":"Listening comprehension, spelling","difficulty_range":[1,6],"default_visual_variant":"ListenAndBuild","content_fields":["prompt","targetWord","extraDistractorCount","customDistractors","visualVariant","promptAudio","hintMode","wordRevealDatabase"],"variants":["listening_spelling"],"typical_stations":["chest","cart","tombstone","exam_table"]}}]$seed$::jsonb) as entries(kind text, external_id text, name text, description text, status text, image_path text, metadata jsonb) on conflict (kind, external_id) do update set name = excluded.name, description = excluded.description, status = excluded.status, image_path = excluded.image_path, metadata = excluded.metadata, updated_at = now();
